def max_distance(t, v):
    total_distance = 0
    for i in range(N):
        if i == 0:
            # Accelerate to v[i] in t[i] seconds
            acceleration_time = min(v[i], t[i]) // 2
            if acceleration_time > 0:
                total_distance += acceleration_time * (acceleration_time + 1)
            remaining_time = t[i] - 2 * acceleration_time
            if remaining_time > 0:
                total_distance += v[i] * remaining_time
            if acceleration_time < v[i]:
                total_distance += (v[i] - acceleration_time) * (v[i] - acceleration_time + 1) // 2
        elif i == N - 1:
            # Decelerate to 0 in t[i] seconds
            deceleration_time = min(v[i], t[i]) // 2
            if deceleration_time > 0:
                total_distance += deceleration_time * (deceleration_time + 1)
            remaining_time = t[i] - 2 * deceleration_time
            if remaining_time > 0:
                total_distance += v[i] * remaining_time
            if deceleration_time < v[i]:
                total_distance += (v[i] - deceleration_time) * (v[i] - deceleration_time + 1) // 2
        else:
            # Maintain constant speed v[i] for t[i] seconds
            total_distance += v[i] * t[i]
    return total_distance / 2

